/* flash.media backend on NDSP. Sounds are raw PCM16 mono 22050 Hz files
 * (generated by tools/convert_assets.py --audio from the original MP3s).
 *
 * Short effects are loaded once into linear memory. Long files (music,
 * ambient loops: ~36 MB in total, more than the linear heap of an Old 3DS)
 * are streamed from the SD card through two small buffers per voice that are
 * refilled from FlashMediaBackend_finished, which flash/media.c polls every
 * frame for every live channel. One NDSP channel per playing voice. */
#include <3ds.h>
#include "../../flash/media.h"
#include "../common/session.h"

#define MAX_SOUNDS 48
#define MAX_VOICES 24
#define RATE 22050
#define STREAM_THRESHOLD (512 * 1024) /* bytes: larger files are streamed */
#define CHUNK 16384                   /* samples per stream buffer (0.74 s) */
#define LOOP_FOREVER 9999             /* Flixel's "loop forever" loop count */

extern const char *Embed_root;

typedef struct LoadedSound {
	char name[96];
	char path[256];
	int16_t *data; /* NULL when streamed */
	uint32_t samples;
	bool music; /* under /assets/music/: silenced by the Music setting */
} LoadedSound;

typedef struct Voice {
	bool used;
	int sound;
	int32_t loopsLeft;
	Number volume, pan;
	/* in-memory */
	ndspWaveBuf buf;
	/* streamed */
	bool streamed, eof;
	FILE *file;
	int16_t *chunk[2];
	ndspWaveBuf wbuf[2];
	uint32_t readPos;  /* next sample to read from the file */
	uint32_t consumed; /* samples in buffers that finished playing */
	bool queued[2];
} Voice;

/* diagnostics for runtime.log */
uint32_t Media_playCalls, Media_playFailed, Media_loadFailed;
int Media_lastFail;
static LoadedSound sounds[MAX_SOUNDS];
static int soundCount;
static Voice voices[MAX_VOICES];

int FlashMediaBackend_load(const char *embedName, Number *lengthMs)
{
	for (int i = 0; i < soundCount; i++)
		if (strcmp(sounds[i].name, embedName) == 0) {
			*lengthMs = sounds[i].samples * 1000.0 / RATE;
			return i;
		}
	if (soundCount >= MAX_SOUNDS)
		return -1;
	LoadedSound *s = &sounds[soundCount];
	snprintf(s->name, sizeof s->name, "%s", embedName);
	/* "/assets/sound/hit.mp3" -> <root>/assets/sound/hit.mp3.pcm */
	snprintf(s->path, sizeof s->path, "%s/%s.pcm", Embed_root, embedName[0] == '/' ? embedName + 1 : embedName);
	s->data = NULL;
	s->samples = 0;
	s->music = strstr(embedName, "/music/") != NULL;
	FILE *f = fopen(s->path, "rb");
	if (!f)
		Media_loadFailed++;
	if (f) {
		fseek(f, 0, SEEK_END);
		long size = ftell(f);
		fseek(f, 0, SEEK_SET);
		s->samples = (uint32_t)(size / 2);
		if (size > 0 && size <= STREAM_THRESHOLD) {
			s->data = linearAlloc((size_t)size);
			if (s->data && fread(s->data, 1, (size_t)size, f) == (size_t)size)
				DSP_FlushDataCache(s->data, (u32)size);
			else if (s->data) {
				linearFree(s->data);
				s->data = NULL; /* fall back to streaming */
			}
		}
		fclose(f);
	}
	*lengthMs = s->samples * 1000.0 / RATE;
	return soundCount++;
}

static void apply_mix(int voice)
{
	Voice *vo = &voices[voice];
	Number volume = vo->volume, pan = vo->pan;
	if (sounds[vo->sound].music && !FlashMediaBackend_musicEnabled)
		volume = 0;
	float mix[12] = {0};
	if (pan < -1) pan = -1;
	if (pan > 1) pan = 1;
	/* SoundTransform.pan: -1 left .. 1 right, linear like Flash */
	mix[0] = (float)(volume * (pan > 0 ? 1 - pan : 1));
	mix[1] = (float)(volume * (pan < 0 ? 1 + pan : 1));
	ndspChnSetMix(voice, mix);
}

void FlashMediaBackend_refreshMix(void)
{
	for (int v = 0; v < MAX_VOICES; v++)
		if (voices[v].used)
			apply_mix(v);
}

/* Fills stream buffer i and queues it. Returns false at the end of the sound. */
static bool stream_fill(int v, int i)
{
	Voice *vo = &voices[v];
	LoadedSound *s = &sounds[vo->sound];
	uint32_t filled = 0;
	while (filled < CHUNK && !vo->eof) {
		if (vo->readPos >= s->samples) {
			if (vo->loopsLeft >= LOOP_FOREVER || vo->loopsLeft > 0) {
				if (vo->loopsLeft < LOOP_FOREVER)
					vo->loopsLeft--;
				vo->readPos = 0;
				fseek(vo->file, 0, SEEK_SET);
			} else {
				vo->eof = true;
				break;
			}
		}
		uint32_t want = CHUNK - filled;
		if (want > s->samples - vo->readPos)
			want = s->samples - vo->readPos;
		size_t got = fread(vo->chunk[i] + filled, 2, want, vo->file);
		if (got == 0) {
			vo->readPos = s->samples; /* short file: treat as its end */
			continue;
		}
		filled += (uint32_t)got;
		vo->readPos += (uint32_t)got;
	}
	if (filled == 0)
		return false;
	DSP_FlushDataCache(vo->chunk[i], filled * 2);
	memset(&vo->wbuf[i], 0, sizeof vo->wbuf[i]);
	vo->wbuf[i].data_vaddr = vo->chunk[i];
	vo->wbuf[i].nsamples = filled;
	ndspChnWaveBufAdd(v, &vo->wbuf[i]);
	vo->queued[i] = true;
	return true;
}

int FlashMediaBackend_play(int soundId, Number startTimeMs, int32_t loops, Number volume, Number pan)
{
	Media_playCalls++;
	if (soundId < 0 || soundId >= soundCount || sounds[soundId].samples == 0) {
		Media_playFailed++;
		Media_lastFail = soundId;
		return -1;
	}
	for (int v = 0; v < MAX_VOICES; v++) {
		if (voices[v].used)
			continue;
		Voice *vo = &voices[v];
		LoadedSound *s = &sounds[soundId];
		uint32_t start = (uint32_t)(startTimeMs * RATE / 1000.0);
		if (start >= s->samples)
			start = 0;
		ndspChnReset(v);
		ndspChnSetInterp(v, NDSP_INTERP_LINEAR);
		ndspChnSetRate(v, RATE);
		ndspChnSetFormat(v, NDSP_FORMAT_MONO_PCM16);
		vo->sound = soundId;
		vo->volume = volume;
		vo->pan = pan;
		apply_mix(v);
		vo->loopsLeft = loops;
		vo->streamed = s->data == NULL;
		if (!vo->streamed) {
			memset(&vo->buf, 0, sizeof vo->buf);
			vo->buf.data_vaddr = s->data + start;
			vo->buf.nsamples = s->samples - start;
			vo->buf.looping = loops >= LOOP_FOREVER;
			ndspChnWaveBufAdd(v, &vo->buf);
		} else {
			if (vo->chunk[0] == NULL) {
				vo->chunk[0] = linearAlloc(CHUNK * 2);
				vo->chunk[1] = linearAlloc(CHUNK * 2);
				if (vo->chunk[0] == NULL || vo->chunk[1] == NULL)
					return -1;
			}
			vo->file = fopen(s->path, "rb");
			if (vo->file == NULL)
				return -1;
			fseek(vo->file, (long)start * 2, SEEK_SET);
			vo->readPos = start;
			vo->consumed = start;
			vo->eof = false;
			vo->queued[0] = vo->queued[1] = false;
			stream_fill(v, 0);
			stream_fill(v, 1);
		}
		vo->used = true;
		return v;
	}
	Media_playFailed++; /* no free voice */
	return -1;
}

void FlashMediaBackend_stop(int voice)
{
	if (voice < 0 || voice >= MAX_VOICES)
		return;
	Voice *vo = &voices[voice];
	ndspChnWaveBufClear(voice);
	if (vo->file != NULL) {
		fclose(vo->file);
		vo->file = NULL;
	}
	vo->used = false;
}

void FlashMediaBackend_setTransform(int voice, Number volume, Number pan)
{
	if (voice >= 0 && voice < MAX_VOICES && voices[voice].used) {
		voices[voice].volume = volume;
		voices[voice].pan = pan;
		apply_mix(voice);
	}
}

Number FlashMediaBackend_position(int voice)
{
	if (voice < 0 || voice >= MAX_VOICES || !voices[voice].used)
		return 0;
	Voice *vo = &voices[voice];
	uint32_t pos = ndspChnGetSamplePos(voice);
	if (vo->streamed) {
		uint32_t len = sounds[vo->sound].samples;
		pos = len ? (vo->consumed + pos) % len : 0;
	}
	return pos * 1000.0 / RATE;
}

bool FlashMediaBackend_finished(int voice)
{
	if (voice < 0 || voice >= MAX_VOICES || !voices[voice].used)
		return true;
	Voice *vo = &voices[voice];
	if (vo->streamed) {
		/* refill the buffers the DSP has finished with */
		for (int i = 0; i < 2; i++)
			if (vo->queued[i] && vo->wbuf[i].status == NDSP_WBUF_DONE) {
				vo->consumed += vo->wbuf[i].nsamples;
				vo->queued[i] = false;
				stream_fill(voice, i);
			}
		return !vo->queued[0] && !vo->queued[1];
	}
	if (vo->buf.status != NDSP_WBUF_DONE)
		return false;
	if (vo->loopsLeft > 0 && !vo->buf.looping) {
		/* replay for the remaining loop count */
		vo->loopsLeft--;
		vo->buf.data_vaddr = sounds[vo->sound].data;
		vo->buf.nsamples = sounds[vo->sound].samples;
		ndspChnWaveBufAdd(voice, &vo->buf);
		return false;
	}
	return true;
}
